import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { Bot, MapPinned, Sparkles } from "lucide-react";
import { useAppState } from "../state/AppState";
import { mergeClinics } from "../lib/clinics";
import MissionForm from "../components/MissionForm";
import AgentFeed from "../components/AgentFeed";
import ClinicMap from "../components/ClinicMap";
import ClinicCard from "../components/ClinicCard";
import ApplyModal from "../components/ApplyModal";
import ErrorBoundary from "../components/ErrorBoundary";
import { useFlip } from "../hooks/useFlip";

function EmptyState() {
  const steps = [
    { icon: MapPinned, title: "Find the clinics", text: "Searches your city for family practices." },
    { icon: Bot, title: "Read every website", text: "Agents check who's accepting new patients." },
    { icon: Sparkles, title: "Rank them for you", text: "Sorted for your coverage, language and distance." },
  ];
  return (
    <div className="card animate-card-in p-8">
      <h2 className="text-xl font-bold">Your results will appear here</h2>
      <p className="mt-1 text-sm text-slate-500">
        Press <b className="text-ink">Launch CareScout</b> to start. A live search takes a few minutes; Demo mode shows saved results instantly.
      </p>
      <ol className="mt-6 grid gap-4 sm:grid-cols-3">
        {steps.map(({ icon: Icon, title, text }, i) => (
          <li key={title} className="rounded-xl bg-slate-50 p-4">
            <div className="flex items-center gap-2 text-sm font-semibold text-ink">
              <span className="flex h-6 w-6 items-center justify-center rounded-full bg-ink text-xs text-paper">{i + 1}</span>
              {title}
            </div>
            <div className="mt-2 flex items-start gap-2 text-xs text-slate-500">
              <Icon className="h-4 w-4 shrink-0 text-pine-600" />
              {text}
            </div>
          </li>
        ))}
      </ol>
    </div>
  );
}

export default function FindPage() {
  const { search, setSearch, mission, launch, refreshWatchCount, publicDemo } = useAppState();
  const { state, stop, reset } = mission;
  const [params, setParams] = useSearchParams();
  const [selectedUrl, setSelectedUrl] = useState(null);
  const [applyFor, setApplyFor] = useState(null);
  const cardRefs = useRef({});
  const email = search.email.trim();

  const clinics = useMemo(() => mergeClinics(state.scanned, state.urls, state.ranked), [state.scanned, state.urls, state.ranked]);
  // cards glide to their ranked position when ranking arrives
  useFlip(clinics.map((c) => c.url), cardRefs);

  // /find?demo=1 (from the home page): switch on Demo mode and run it straight away (once).
  const demoStarted = useRef(false);
  useEffect(() => {
    if (params.get("demo") === "1" && !demoStarted.current) {
      demoStarted.current = true;
      setParams({}, { replace: true });
      setSearch((s) => ({ ...s, useCache: true }));
      if (!state.running) launch({ useCache: true });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onLaunch = () => {
    setSelectedUrl(null);
    launch();
  };

  const selectClinic = useCallback((url) => {
    setSelectedUrl(url);
    cardRefs.current[url]?.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }, []);

  return (
    <div className="container-page space-y-4 py-8">
      <div className="mb-2">
        <h1 className="text-3xl font-bold tracking-tight">Find a family doctor</h1>
        <p className="mt-1 text-slate-500">Tell CareScout where you are and what you need. Agents check each clinic's website for you.</p>
      </div>

      <MissionForm values={search} onChange={setSearch} onLaunch={onLaunch} onStop={stop} running={state.running} publicDemo={publicDemo} />
      <AgentFeed state={state} onStop={stop} onReset={reset} />

      {clinics.length > 0 ? (
        <div className="grid grid-cols-1 gap-4 lg:grid-cols-5">
          <div className="min-w-0 lg:col-span-2">
            <div className="h-[360px] lg:sticky lg:top-24 lg:h-[calc(100vh-8rem)]">
              <ErrorBoundary label="The map">
                <ClinicMap clinics={clinics} selectedUrl={selectedUrl} onSelect={selectClinic} />
              </ErrorBoundary>
            </div>
          </div>
          <div className="min-w-0 space-y-3 lg:col-span-3">
            {clinics.map((c, i) => (
              <ErrorBoundary key={c.url} label={`The card for ${c.name || c.url}`}>
                <ClinicCard
                  ref={(el) => (cardRefs.current[c.url] = el)}
                  clinic={c}
                  enterDelay={Math.min(i, 8) * 45}
                  selected={c.url === selectedUrl}
                  onSelect={setSelectedUrl}
                  onApply={setApplyFor}
                  email={email}
                  city={search.city}
                  onWatched={refreshWatchCount}
                />
              </ErrorBoundary>
            ))}
          </div>
        </div>
      ) : (
        !state.running && state.log.length === 0 && <EmptyState />
      )}

      {applyFor && <ApplyModal clinic={applyFor} defaults={search} onClose={() => setApplyFor(null)} />}
    </div>
  );
}
import { useCallback, useReducer, useRef } from "react";
import { api } from "../api";
import { isFailedScan } from "../lib/clinics";

export const STAGES = [
  { key: "discover", label: "Scout" },
  { key: "scan", label: "Browser Swarm" },
  { key: "rank", label: "Triage" },
  { key: "watch", label: "Watchdog" },
  { key: "done", label: "Done" },
];

const initial = {
  running: false,
  stage: null, // current stage key
  stageStatus: {}, // { discover: "active" | "done" | "error" | "skipped" }
  log: [], // [{ id, time, kind, stage, text }]
  urls: [], // discovered order
  agents: {}, // { [url]: "queued" | "scanning" | "done" }
  scanned: {}, // { [url]: Clinic }
  ranked: null, // RankedClinic[]
  watched: [], // Watch[]
  summary: null,
  error: null, // fatal error (request failed / stream broke)
  stopped: false,
};

let logId = 0;
const entry = (kind, text, stage) => ({ id: ++logId, time: new Date(), kind, text, stage });

function markStage(stageStatus, stage) {
  const next = { ...stageStatus };
  for (const s of STAGES) {
    if (s.key === stage) break;
    if (next[s.key] === "active" || !next[s.key]) next[s.key] = next[s.key] === "error" ? "error" : "done";
  }
  if (next[stage] !== "error") next[stage] = "active";
  return next;
}

function reducer(state, action) {
  switch (action.type) {
    case "start":
      return { ...initial, running: true, log: [entry("info", "Launching CareScout mission...")] };
    case "event":
      return applyEvent(state, action.event);
    case "fail":
      return { ...state, running: false, error: action.message, log: [...state.log, entry("error", action.message)] };
    case "stopped":
      return { ...state, running: false, stopped: true, log: [...state.log, entry("info", "Mission stopped.")] };
    case "finished":
      return { ...state, running: false };
    case "clinic_updated":
      return { ...state, scanned: { ...state.scanned, [action.clinic.url]: { ...state.scanned[action.clinic.url], ...action.clinic } } };
    case "reset":
      return initial;
    default:
      return state;
  }
}

function applyEvent(state, e) {
  switch (e.type) {
    case "stage": {
      const skipped = e.stage === "watch" && /skipped/i.test(e.message);
      const stageStatus = markStage(state.stageStatus, e.stage);
      if (skipped) stageStatus.watch = "skipped";
      return { ...state, stage: e.stage, stageStatus, log: [...state.log, entry("stage", e.message, e.stage)] };
    }
    case "discovered": {
      const agents = Object.fromEntries(e.urls.map((u) => [u, "queued"]));
      return {
        ...state,
        urls: e.urls,
        agents,
        log: [...state.log, entry("info", `Found ${e.urls.length} clinic website${e.urls.length === 1 ? "" : "s"}.`, "discover")],
      };
    }
    case "agent_status": {
      // "Up to date (checked 2 h ago)" -> done; "Reading...", "Agent started...", "Following..." -> scanning; else queued
      const status = /^up to date/i.test(e.message) ? "done" : /reading|started|following/i.test(e.message) ? "scanning" : "queued";
      return { ...state, agents: { ...state.agents, [e.url]: status } };
    }
    case "clinic_scanned": {
      const c = e.clinic;
      const urls = state.urls.includes(c.url) ? state.urls : [...state.urls, c.url];
      const text = isFailedScan(c) ? `Couldn't check ${c.url.replace(/^https?:\/\//, "")}` : `${c.name}: ${c.status}`;
      return {
        ...state,
        urls,
        agents: { ...state.agents, [c.url]: "done" },
        scanned: { ...state.scanned, [c.url]: c },
        log: [...state.log, entry("result", text, "scan")],
      };
    }
    case "ranked":
      return {
        ...state,
        ranked: e.ranked_clinics,
        log: [...state.log, entry("info", `Ranked ${e.ranked_clinics.length} clinics.`, "rank")],
      };
    case "watched":
      return {
        ...state,
        watched: e.clinics,
        log: [...state.log, entry("info", `Watching ${e.count} full clinic${e.count === 1 ? "" : "s"} for openings.`, "watch")],
      };
    case "error":
      return {
        ...state,
        stageStatus: { ...state.stageStatus, [e.stage]: "error" },
        log: [...state.log, entry("error", e.message, e.stage)],
      };
    case "done": {
      const stageStatus = { ...state.stageStatus };
      for (const s of STAGES) if (stageStatus[s.key] === "active") stageStatus[s.key] = "done";
      stageStatus.done = "done";
      const s = e.summary || {};
      return {
        ...state,
        running: false,
        stage: "done",
        stageStatus,
        summary: e.summary,
        log: [...state.log, entry("done", `Done in ${s.duration_s ?? "?"}s: ${s.accepting_count ?? 0} accepting, ${s.waitlist_count ?? 0} waitlist, ${s.closed_count ?? 0} closed.`, "done")],
      };
    }
    default:
      return state;
  }
}

/** Runs POST /api/mission/stream and keeps all of its live state. */
export function useMission() {
  const [state, dispatch] = useReducer(reducer, initial);
  const controller = useRef(null);

  const start = useCallback(async (body) => {
    controller.current?.abort();
    const ctrl = new AbortController();
    controller.current = ctrl;
    dispatch({ type: "start" });
    try {
      await api.missionStream(body, (event) => dispatch({ type: "event", event }), ctrl.signal);
      dispatch({ type: "finished" });
    } catch (e) {
      if (e.name === "AbortError") return; // stop() already updated the state
      dispatch({ type: "fail", message: e.message || "The mission failed." });
    } finally {
      if (controller.current === ctrl) controller.current = null;
    }
  }, []);

  const stop = useCallback(() => {
    if (controller.current) {
      controller.current.abort();
      controller.current = null;
      dispatch({ type: "stopped" });
    }
  }, []);

  const reset = useCallback(() => {
    controller.current?.abort();
    controller.current = null;
    dispatch({ type: "reset" });
  }, []);

  // Replace one clinic's result (e.g. after "Re-check") without re-running the search.
  const updateClinic = useCallback((clinic) => dispatch({ type: "clinic_updated", clinic }), []);

  return { state, start, stop, reset, updateClinic };
}
import { Clock, Info, Loader2, Rocket, Square } from "lucide-react";
import { COVERAGE_OPTIONS, LANGUAGE_OPTIONS, MAX_CLINICS } from "../config";

/** The mission search bar. Controlled by the page (values / onChange) so other views can reuse the same email/postal code. */
export default function MissionForm({ values, onChange, onLaunch, onStop, running, publicDemo = false }) {
  const set = (key) => (e) => onChange({ ...values, [key]: e.target.type === "checkbox" ? e.target.checked : e.target.value });
  const savedOnly = publicDemo || values.useCache;
  const count = Number(values.maxClinics) || 0;

  const setCount = (e) => {
    const raw = e.target.value;
    onChange({ ...values, maxClinics: raw === "" ? "" : Math.max(1, Math.min(MAX_CLINICS, Math.round(Number(raw)) || 1)) });
  };

  const submit = (e) => {
    e.preventDefault();
    if (!running) onLaunch();
  };

  return (
    <form onSubmit={submit} className="card p-4">
      <div className="grid grid-cols-2 gap-3 md:grid-cols-6">
        <div className="col-span-2 md:col-span-1">
          <label className="label" htmlFor="city">City</label>
          <input id="city" className="input" value={values.city} onChange={set("city")} placeholder="London, ON" required />
        </div>
        <div>
          <label className="label" htmlFor="postal">Postal Code</label>
          <input id="postal" className="input" value={values.postalCode} onChange={set("postalCode")} placeholder="N6A 3K7" />
        </div>
        <div>
          <label className="label" htmlFor="coverage">Coverage</label>
          <select id="coverage" className="input" value={values.coverage} onChange={set("coverage")}>
            {COVERAGE_OPTIONS.map((o) => <option key={o}>{o}</option>)}
          </select>
        </div>
        <div>
          <label className="label" htmlFor="language">Language</label>
          <select id="language" className="input" value={values.language} onChange={set("language")}>
            {LANGUAGE_OPTIONS.map((o) => <option key={o}>{o}</option>)}
          </select>
        </div>
        <div className="col-span-2">
          <label className="label" htmlFor="email">Email <span className="font-normal text-slate-400">(optional: auto-watch full clinics)</span></label>
          <input id="email" type="email" className="input" value={values.email} onChange={set("email")} placeholder="you@example.com" />
        </div>
      </div>

      <div className="mt-3 grid gap-3 border-t border-slate-100 pt-3 md:grid-cols-[150px,1fr] md:items-start">
        <div>
          <label className="label" htmlFor="max-clinics">Clinics to check</label>
          <input
            id="max-clinics"
            type="number"
            inputMode="numeric"
            min={1}
            max={MAX_CLINICS}
            className="input"
            value={values.maxClinics}
            onChange={setCount}
            onBlur={() => !count && onChange({ ...values, maxClinics: 5 })}
            aria-describedby="max-clinics-note"
          />
        </div>
        <div id="max-clinics-note" className="flex items-start gap-2 rounded-lg bg-slate-50 px-3 py-2 text-xs leading-relaxed text-slate-600 md:mt-5">
          <Clock className="mt-0.5 h-3.5 w-3.5 shrink-0 text-pine-600" />
          {savedOnly ? (
            <span>Up to {MAX_CLINICS} clinics. Saved results load instantly, so a bigger number doesn't make you wait.</span>
          ) : (
            <span>
              Up to {MAX_CLINICS} clinics. The more you add, the longer it can take: clinics checked in the last 12 hours load instantly,
              most others take a few seconds, but sites that need a browser agent take 1 to 3 minutes each (two at a time).
            </span>
          )}
        </div>
      </div>

      <div className="mt-3 flex flex-wrap items-center justify-between gap-3">
        {publicDemo ? (
          <p className="flex items-start gap-2 text-sm text-slate-600">
            <Info className="mt-0.5 h-4 w-4 shrink-0 text-pine-600" />
            <span>This public demo shows saved results from the CareScout database. Live checks run when CareScout is set up locally.</span>
          </p>
        ) : (
          <div className="flex flex-wrap items-center gap-x-5 gap-y-2">
            <label className="flex cursor-pointer select-none items-center gap-2 text-sm text-slate-600">
              <input type="checkbox" className="h-4 w-4 rounded accent-emerald-600" checked={values.useCache} onChange={set("useCache")} />
              Use Cache (Demo Mode)
              <span className="text-xs text-slate-400">saved results only, instant</span>
            </label>
            <label className={`flex select-none items-center gap-2 text-sm ${values.useCache ? "cursor-not-allowed text-slate-300" : "cursor-pointer text-slate-600"}`}>
              <input type="checkbox" className="h-4 w-4 rounded accent-emerald-600" checked={values.recheckAll && !values.useCache}
                disabled={values.useCache} onChange={set("recheckAll")} />
              Re-check every clinic
              <span className={`text-xs ${values.useCache ? "text-slate-300" : "text-slate-400"}`}>slower, ignores saved results</span>
            </label>
          </div>
        )}
        {running ? (
          <div className="flex items-center gap-2">
            <span className="flex items-center gap-1.5 text-sm text-slate-500">
              <Loader2 className="h-4 w-4 animate-spin" /> Agents working...
            </span>
            <button type="button" onClick={onStop} className="btn-secondary">
              <Square className="h-4 w-4" /> Stop
            </button>
          </div>
        ) : (
          <button type="submit" className="btn-primary px-5">
            <Rocket className="h-4 w-4" /> Launch CareScout
          </button>
        )}
      </div>
    </form>
  );
}
import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import { api } from "../api";
import { DEFAULT_SEARCH, MAX_CLINICS } from "../config";
import { useMission } from "../hooks/useMission";

const AppStateContext = createContext(null);

/**
 * State shared by every page: the search form, the running mission (so it keeps going while you browse other
 * pages), the opening-alert banner and the Watchdog count shown in the nav.
 */
export function AppStateProvider({ children }) {
  const [search, setSearch] = useState(DEFAULT_SEARCH);
  const mission = useMission();
  const [alert, setAlert] = useState(null);
  const [watchCount, setWatchCount] = useState(0);
  // The backend tells us if it's a public deployment: then only saved (demo) results are available.
  const [publicDemo, setPublicDemo] = useState(false);
  const email = search.email.trim();

  useEffect(() => {
    api
      .health()
      .then((h) => {
        if (h.public_demo) {
          setPublicDemo(true);
          setSearch((s) => ({ ...s, useCache: true }));
        }
      })
      .catch(() => {
        /* backend unreachable: pages show their own errors */
      });
  }, []);

  const refreshWatchCount = useCallback(async () => {
    try {
      const r = await api.listWatches(email.includes("@") ? email : undefined);
      setWatchCount(r.watched_clinics.length);
    } catch {
      /* backend offline: keep the old count */
    }
  }, [email]);

  useEffect(() => {
    refreshWatchCount();
  }, [refreshWatchCount]);

  useEffect(() => {
    if (mission.state.watched.length) refreshWatchCount(); // a mission auto-enrolled full clinics
  }, [mission.state.watched, refreshWatchCount]);

  const launch = useCallback(
    (overrides = {}) => {
      const s = { ...search, ...overrides };
      mission.start({
        city: s.city.trim() || "London, ON",
        user_postal_code: s.postalCode.trim() || null,
        preferences: [],
        language: s.language,
        coverage_type: s.coverage,
        user_email: s.email.trim() || null,
        auto_watch_closed: true,
        use_cache: s.useCache || publicDemo,
        max_clinics: Math.max(1, Math.min(MAX_CLINICS, Number(s.maxClinics) || 5)),
        refresh: s.recheckAll ? "all" : "auto",
      });
    },
    [search, mission, publicDemo],
  );

  const value = useMemo(
    () => ({ search, setSearch, mission, launch, alert, setAlert, watchCount, setWatchCount, refreshWatchCount, publicDemo }),
    [search, mission, launch, alert, watchCount, refreshWatchCount, publicDemo],
  );
  return <AppStateContext.Provider value={value}>{children}</AppStateContext.Provider>;
}

export function useAppState() {
  const ctx = useContext(AppStateContext);
  if (!ctx) throw new Error("useAppState must be used inside <AppStateProvider>");
  return ctx;
}

import { useEffect, useRef, useState } from "react";
import { AlertTriangle, Check, ChevronDown, ChevronUp, Loader2, MinusCircle, RotateCcw, Square } from "lucide-react";
import { STAGES } from "../hooks/useMission";

function StepIcon({ status }) {
  if (status === "active") return <Loader2 className="h-4 w-4 animate-spin" />;
  if (status === "done") return <Check className="h-4 w-4" />;
  if (status === "error") return <AlertTriangle className="h-4 w-4" />;
  if (status === "skipped") return <MinusCircle className="h-4 w-4" />;
  return null;
}

const STEP_STYLE = {
  active: "bg-brand text-white ring-brand",
  done: "bg-emerald-50 text-emerald-700 ring-emerald-200",
  error: "bg-rose-50 text-rose-700 ring-rose-200",
  skipped: "bg-slate-100 text-slate-500 ring-slate-200",
};

const KIND_DOT = { stage: "bg-emerald-500", result: "bg-sky-500", error: "bg-rose-500", done: "bg-emerald-600", info: "bg-slate-300" };

/** Live progress bar + compact log for POST /api/mission/stream (state comes from useMission). */
export default function AgentFeed({ state, onStop, onReset }) {
  const [open, setOpen] = useState(true);
  const logEnd = useRef(null);
  const { running, stageStatus, log, agents, error, summary } = state;

  useEffect(() => {
    if (open) logEnd.current?.scrollIntoView({ block: "nearest" });
  }, [log.length, open]);

  if (!running && log.length === 0) return null;

  // index of the furthest stage that has started (drives the progress line)
  const reached = Math.max(0, ...STAGES.map((s, i) => (stageStatus[s.key] ? i : 0)));
  const agentCounts =Object.values(agents).reduce((acc, s) => ({ ...acc, [s]: (acc[s] || 0) + 1 }), {});

  return (
    <section className="card animate-card-in p-4" aria-live="polite">
      <div className="flex items-center justify-between gap-2">
        <h2 className="text-sm font-semibold text-slate-900">Live agent activity</h2>
        <div className="flex items-center gap-1">
          {running ? (
            <button onClick={onStop} className="btn-ghost py-1 text-xs"><Square className="h-3.5 w-3.5" /> Stop</button>
          ) : (
            <button onClick={onReset} className="btn-ghost py-1 text-xs"><RotateCcw className="h-3.5 w-3.5" /> Reset</button>
          )}
          <button onClick={() => setOpen((o) => !o)} className="btn-ghost px-2 py-1" aria-label={open ? "Hide log" : "Show log"}>
            {open ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
          </button>
        </div>
      </div>

      {/* step-by-step progress: the line between the steps fills up to the stage that's running */}
      <ol className="relative mt-3 grid grid-cols-5 gap-2">
        <span className="absolute left-[10%] right-[10%] top-4 h-0.5 -translate-y-1/2 rounded-full bg-slate-200" aria-hidden="true" />
        <span
          className="absolute left-[10%] right-[10%] top-4 h-0.5 origin-left -translate-y-1/2 rounded-full bg-pine-500 transition-transform duration-700 ease-flow"
          style={{ transform: `translateY(-50%) scaleX(${reached / (STAGES.length - 1)})` }}
          aria-hidden="true"
        />
        {STAGES.map((s, i) => {
          const status = stageStatus[s.key];
          return (
            <li key={s.key} className="relative flex flex-col items-center gap-1 text-center">
              <div className={`flex h-8 w-8 items-center justify-center rounded-full text-xs font-semibold ring-1 transition-colors duration-500 ${status === "active" ? "animate-pop-in" : ""} ${STEP_STYLE[status] || "bg-surface text-slate-400 ring-slate-200"}`}>
                <StepIcon status={status} /> {!status && i + 1}
              </div>
              <span className={`text-[11px] font-medium sm:text-xs ${status ? "text-slate-700" : "text-slate-400"}`}>{s.label}</span>
            </li>
          );
        })}
      </ol>

      {Object.keys(agents).length > 0 && (
        <div className="mt-3 flex flex-wrap gap-2 text-xs text-slate-500">
          <span className="badge bg-slate-50 text-slate-600 ring-slate-200">{agentCounts.queued || 0} queued</span>
          <span className="badge bg-sky-50 text-sky-700 ring-sky-200">{agentCounts.scanning || 0} scanning</span>
